pub fn route(method: &str, target: &str) -> u16 {
    match target.split('?').next().unwrap_or("") {
        "/tasks" => match method {
            "GET" => 200,
            "POST" => 201,
            _ => 405,
        },
        "/health" => {
            if method == "GET" {
                200
            } else {
                405
            }
        }
        _ => 404,
    }
}

fn main() {
    assert_eq!(route("GET", "/tasks?limit=5"), 200, "case 1");
    assert_eq!(route("GET", "/missing"), 404, "case 2");
    assert_eq!(route("DELETE", "/tasks"), 405, "case 3");
    assert_eq!(route("POST", "/tasks"), 201, "case 4");
    assert_eq!(route("GET", "/Tasks"), 404, "case 5");
    assert_eq!(route("POST", "/health"), 405, "case 6");
    println!("worked example passed");
}

